{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Emtricitabine, a closely related pyrimidine NRTI with a modified sugar, has an absolute oral bioavailability of 93% in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Lamivudine, another close pyrimidine NRTI analogue, shows a mean absolute oral bioavailability of 87% from an oral solution in fasted patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Zalcitabine, a dideoxynucleoside analogue with a pyrimidine base, has an absolute oral bioavailability of 88% in patients with AIDS/ARC, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Cladribine, a less favorable nucleoside analogue, still shows oral bioavailability of 46% while fasting, remaining well above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is stavudine, a thymidine NRTI. The highest-transfer analogues are pyrimidine NRTIs with measured absolute oral bioavailability values of 66-93%, all above the 20% threshold. Even less favorable nucleoside analogues such as cladribine remain above 20%. The few sub-20% didanosine values reflect acid lability and are not transferable to this thymidine-based query. Therefore the prediction is high oral bioavailability.",
  "evidence_gaps": [
    "No direct stavudine oral bioavailability record is included; the prediction relies on close NRTI analogues.",
    "Didanosine, the only analogue with some sub-20% values, differs in acid lability and purine base, limiting transferability of those low-F records to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

